import { useState } from 'react'
import { useAuthUser } from 'react-auth-kit'
import { Helmet } from 'react-helmet-async'
import { useSearchParams } from 'react-router-dom'

import { Box, Button, Container, Grid, Stack, Typography, useMediaQuery, useTheme } from '@mui/material'

import type { ClubMemberForAuth } from 'src/models/clubMember'

import ConfirmDialog from 'src/components/ConfirmDialog'
import CouponCard from 'src/components/CouponCard'
import PageTitleWrapper from 'src/components/PageTitleWrapper'

import { useGetClubPointCoupon, useGetRecruitList, usePurchaseCoupon, useUseCoupon } from 'src/hooks/api/recruit'

import PointTip from './PointTip'

const RECRUIT_BUMP_COUPON_PRICE = 75

const StorePage: React.FC = () => {
  const theme = useTheme()
  const isMobile = useMediaQuery(theme.breakpoints.down('sm'))
  const authUser = useAuthUser()
  const [searchParams] = useSearchParams()

  const clubs = authUser()?.clubs ?? []
  const clubIdParam = searchParams.get('clubId')
  const queryClubId = clubIdParam ? Number(clubIdParam) : undefined
  const selectedClubId = queryClubId && !Number.isNaN(queryClubId) ? queryClubId : clubs[0]?.id
  const selectedClub = clubs.find((club: ClubMemberForAuth) => club.id === selectedClubId)

  const { data: pointCouponData } = useGetClubPointCoupon(selectedClubId)
  const recruitList = useGetRecruitList(selectedClubId)
  const purchaseCouponMutation = usePurchaseCoupon()
  const useCouponMutation = useUseCoupon()

  const currentPoint = pointCouponData?.point ?? 0
  const availableCoupons = (pointCouponData?.coupons ?? []).filter(c => !c.isUsed && !c.deletedAt)
  const targetRecruit = [...(recruitList.data ?? [])].sort(
    (a, b) => new Date(b.startAt).getTime() - new Date(a.startAt).getTime()
  )[0]
  const canBuyCoupon = !!selectedClubId && currentPoint >= RECRUIT_BUMP_COUPON_PRICE && !purchaseCouponMutation.isLoading
  const canApplyCoupon =
    !!selectedClubId && !!targetRecruit && availableCoupons.length > 0 && !useCouponMutation.isLoading

  const [confirmOpen, setConfirmOpen] = useState(false)

  const handlePurchaseCoupon = () => {
    if (!selectedClubId) return
    purchaseCouponMutation.mutate({ clubId: selectedClubId })
  }

  const handleApplyCoupon = () => {
    if (!selectedClubId || !targetRecruit || availableCoupons.length === 0) return
    useCouponMutation.mutate({ clubId: selectedClubId, couponId: availableCoupons[0].id, recruitId: targetRecruit.id })
    setConfirmOpen(false)
  }

  return (
    <>
      <Helmet>
        <title>포인트 스토어</title>
      </Helmet>
      <PageTitleWrapper>
        <Grid container alignItems="center">
          <Grid item>
            <Stack direction="row" alignItems="baseline">
              <Typography variant={isMobile ? 'h4' : 'h3'} gutterBottom sx={{ marginTop: 1 }}>
                포인트 스토어
              </Typography>
            </Stack>
            <Typography variant={isMobile ? 'body2' : 'subtitle2'}>
              포인트를 적립하고 쿠폰으로 모집 공고를 끌어올릴 수 있어요
            </Typography>
          </Grid>
        </Grid>
      </PageTitleWrapper>
      <Container maxWidth="lg" sx={{ display: 'flex', flexDirection: 'column', alignItems: 'center' }}>
        <Stack spacing={3} sx={{ width: '100%' }}>
          <Box>
            <PointTip />
            <Box
              sx={{
                mt: 2,
                borderRadius: '10px',
                border: '1px solid #E9EDF3',
                backgroundColor: '#FFFFFF',
                padding: isMobile ? '16px 18px' : '18px 24px',
                display: 'flex',
                justifyContent: 'center'
              }}
            >
              <Typography sx={{ fontWeight: 400, fontSize: 16, color: '#223354' }}>
                {selectedClub?.name ?? '선택한'} 동아리가 보유하신 포인트는{' '}
                <Box component="span" sx={{ fontWeight: 700 }}>
                  {currentPoint}P
                </Box>{' '}
                입니다
              </Typography>
            </Box>
          </Box>

          <Box>
            <Typography sx={{ fontWeight: 700, fontSize: 16, mb: 1 }}>보유 쿠폰</Typography>
            <Box
              sx={{
                borderRadius: '10px',
                border: '1px solid #E9EDF3',
                backgroundColor: '#FFFFFF',
                padding: isMobile ? '16px' : '20px 24px'
              }}
            >
              {availableCoupons.length > 0 ? (
                <Stack
                  direction={isMobile ? 'column' : 'row'}
                  justifyContent="space-between"
                  alignItems="center"
                  spacing={2}
                >
                  <Box>
                    <Typography sx={{ color: '#223354', fontSize: 15 }}>
                      모집공고 끌어올리기 쿠폰 - {availableCoupons.length}장
                    </Typography>
                    {!targetRecruit && (
                      <Typography sx={{ color: '#6B778C', fontSize: 13, mt: 0.5 }}>
                        적용 가능한 모집공고가 없습니다.
                      </Typography>
                    )}
                  </Box>
                  <Button
                    variant="contained"
                    color="success"
                    size="small"
                    disabled={!canApplyCoupon}
                    onClick={() => setConfirmOpen(true)}
                  >
                    사용하기
                  </Button>
                </Stack>
              ) : (
                <Typography sx={{ color: '#6B778C', fontSize: 14 }}>보유중인 쿠폰이 없습니다.</Typography>
              )}
            </Box>
          </Box>
          <Stack direction="column" justifyContent="space-between" alignItems="flex-start">
            <Typography sx={{ fontWeight: 700, fontSize: 16, mb: 1 }}>쿠폰 구매</Typography>
            <Box sx={{ width: '100%', display: 'flex', justifyContent: 'flex-start' }}>
              <CouponCard disabled={!canBuyCoupon} onPurchase={handlePurchaseCoupon} />
            </Box>
          </Stack>
        </Stack>
      </Container>
      <ConfirmDialog
        open={confirmOpen}
        handleClose={() => setConfirmOpen(false)}
        handleSubmit={handleApplyCoupon}
        confirmMessage="확인을 누르시면 가장 최근 공고에 끌어올리기 쿠폰이 적용됩니다."
      />
    </>
  )
}

export default StorePage
